import{_ as e,p as r,q as a,s as t,R as o,t as s,Y as p,n}from"./framework-e1bed10d.js";const u="/my-blog/assets/012_01-ddf729b4.png",h="/my-blog/assets/012_02-21540bce.png",c="/my-blog/assets/012_03-805a1a84.png",i="/my-blog/assets/012_04-140b32e2.png",q="/my-blog/assets/012_05-69b1a3a8.png",_={},g=t("h1",{id:"风险评估与信用评分-贷中决策",tabindex:"-1"},[t("a",{class:"header-anchor",href:"#风险评估与信用评分-贷中决策","aria-hidden":"true"},"#"),o(" 风险评估与信用评分（贷中决策）")],-1),l={href:"https://mp.weixin.qq.com/s?__biz=MzIzNzQ5NjU5NQ==&mid=2247484460&idx=1&sn=5367a4d956562987a225886167cde25a&chksm=e8c6f450dfb17d46ff807fceabd9482b625643f2212d3db62b5d5f543eabbe77ec6be1bd0f79",target:"_blank",rel:"noopener noreferrer"},b=p('<hr><p>二、风险评估与信用评分（贷中决策）</p><p>审批环节回答了&quot;贷不贷&quot;，风险评估与信用评分则回答&quot;贷多少、什么价&quot;。这一步把客户的风险画像翻译成一组可执行的信贷参数，业内叫&quot;授信决策&quot;或&quot;定价决策&quot;。很多刚入行的工程师以为风险评估就是拉一份征信报告看看，其实在系统里，它是一条由数据、模型、规则和产品参数共同组成的决策流水线。</p><h3 id="一-征信查询与评估" tabindex="-1"><a class="header-anchor" href="#一-征信查询与评估" aria-hidden="true">#</a> （一）征信查询与评估</h3><p><img src="'+u+'" alt="图片"></p><p><strong>图2-3 征信查询与评估全流程</strong></p><p>风险评估的第一项任务是查征信。个人信贷查人行征信报告，企业信贷查企业征信，互联网贷款还会叠加百行征信、朴道征信等持牌市场化征信机构的补充数据。在信贷系统的架构划分里，持牌征信机构的接入被列为行方系统的一部分，和反欺诈并列，说明在系统架构上，征信是信贷系统从外部获取风险数据的关键通道。征信查询本身是一笔业务动作，要留痕：谁在什么时间以什么理由查了谁的征信，都写入日志，既满足监管对征信查询授权的管理要求，也用于事后审计。</p><p>征信数据进来之后要处理两项任务。一是核验真实性，把客户自报的信息与征信记录对账，识别虚报收入、隐瞒负债、资料造假。二是提取风险特征，比如信用卡张数、贷款笔数、历史逾期次数、近半年查询次数。这里有一个业内都懂的信号：短期内征信被频繁查询，往往意味着客户在多头借贷，是高风险特征。我在民营银行做线上信贷时，把&quot;近三个月征信查询次数&quot;作为准入规则里的一条硬指标，超过阈值直接拒绝，简单粗暴却很有效。</p><h3 id="二-评分卡打分" tabindex="-1"><a class="header-anchor" href="#二-评分卡打分" aria-hidden="true">#</a> （二）评分卡打分</h3><p><img src="'+h+'" alt="图片"></p><p><strong>图2-4 评分卡打分全流程</strong></p><p>征信数据、客户填报数据、第三方数据汇总之后，进入评分环节。评分卡是信贷风险量化最经典的载体，逻辑回归训练的评分卡到今天仍是很多机构的底线模型。评分卡把客户分成若干档：收入、负债比、年龄、职业稳定性、历史行为，每一档都对应一个分数权重，累加得到总分，再映射成违约概率。信贷系统里的评分模型、准入机制、风险预警、反欺诈模型、额度管理、抵质押管理、风险分类共同构成风控管理模块，并由中央控制引擎统一调度。这个中央控制引擎，就是评分和决策规则的执行中枢。</p><p>评分卡的目标是把&quot;经验&quot;变成&quot;可复算的规则&quot;。人工审批看人下菜碟，同样一个客户，不同信贷员可能给出不同结论；评分卡则保证同样输入必然得到同样输出。这一点对系统很重要，因为只有可复算的规则才能进规则引擎，才能在 A/B 测试中验证效果，才能被监管审计。我在国有大行做评级系统时，对公客户的评级要落到十二级乃至更多档位，每一档对应不同的审批权限和定价空间，评级结果直接驱动后面的额度与定价。</p><p>发展到2026年，产业金融的风险评估已经不用客户经理逐户上门收集资料了，核心企业ERP里的订单、发票、入库单数据直接通过接口同步进特征池，自动算成评分变量，人工只需要核对异常单据——我在TCL做供应链金融评分时，八成以上的特征变量都来自核心企业的交易数据，不用再让上下游企业自己提交一堆纸质材料。</p><p>这里要特别说明：零售评分卡是&quot;个人信用打分&quot;，看征信、消费行为、APP操作习惯；对公的风险评估完全是另一套逻辑——不看个人刷了多少外卖、点了多少视频，看的是企业财报、纳税数据、银行流水、行业周期，最后落到内部评级档位，而不是简单的分数排序。产业金融的风险评估更特殊：不单独评估单个上下游企业，而是先评核心企业的整体信用，上下游客户的风险跟着核心企业的资质走，这也是为什么前面说产业金融的准入流程能简化——风险判断的锚点不是单个小客户，是核心企业。</p><p>到2026年，很多机构已经开始把大模型接进评分流程，但不是拿大模型替代评分卡——评分卡的可解释、可审计特性是监管硬要求，谁也不敢动。大模型实际干的是两个辅助活：一是自动把客户上传的财报PDF、尽调报告、核心企业提供的交易说明里的风险文字摘出来，转成结构化特征喂给评分卡，省掉人工录入的活；二是对评分卡在临界区间的客户，帮审批人把相关资料自动汇总成复核摘要，人做最终决策。我在TCL做产业金融评分时，已经在用大模型自动核对应收账款发票的文本信息，比人工一张张看效率高很多，但最终给不给额度，还是评分卡和规则说了算。</p><h3 id="三-从风险到产品-额度、利率、期限、还款方式的翻译" tabindex="-1"><a class="header-anchor" href="#三-从风险到产品-额度、利率、期限、还款方式的翻译" aria-hidden="true">#</a> （三）从风险到产品：额度、利率、期限、还款方式的翻译</h3><p><img src="'+c+'" alt="图片"></p><p><strong>图2-5 风险等级到产品参数的翻译映射</strong></p><p>评分出来之后，决策引擎要回答的问题只有一个：给这个客户什么条件。一笔贷款的核心参数是金额、期限、利率或费率、用途、担保，再叠加还款方式。风险评估的最终产出，就是把这几个参数定下来，写入审批结论。</p><p>这里还要补一条2026年开始执行的硬要求：监管明确所有个人贷款必须向客户明示包含利息、手续费、担保费在内的综合年化成本，系统在定价环节不能只算名义利率，要自动把各项费用加总算出综合年化成本，和审批结论一起输出，客户经理不能再手填这个数——之前很多产品名义利率不高，但加上服务费实际成本远超红线，这个口子现在系统层面直接堵死了。</p><p>定价是整个决策流程里最敏感的一环，因为它直接决定利润和风险的平衡。利率的确定要考虑国家金融政策、贷款风险、同业竞争、与客户的关系以及金融机构的资金筹集成本。信贷系统里，定价通常不是拍脑袋给一个数，而是走定价流程：审批流程里都有&quot;循环定价&quot;节点，定价通过后才进入签约。费率体系把费率拆成标准费率、分群定价、红包折扣、合作方定义几类。标准费率是产品的底线价，分群定价按客户等级差异化，红包折扣用于营销让利，合作方定义则允许资金合作方参与定价。这套费率的细分，说明定价不是单一的利率字段，而是一套&quot;基础价 + 调整项&quot;的费率结构，系统里要支持费率的拆分、叠加和覆盖。</p><p>从用户视角看，金额和期限与产品绑定。产品体系分基础产品和可售产品两层：基础产品是模板，定义了产品的属性取值范围；可售产品在模板上限定具体取值，面向客户销售。一个贷款基础产品定义了利率范围、期限范围、额度上限，可售产品则把利率、期限定成具体值。这就是为什么审批结论里的&quot;金额、期限、利率&quot;从来不是自由填写的，而是产品维度配置约束下的取值。系统在签约前要校验这些参数落在产品允许的范围内。</p><p>还款方式的选择往往被低估，但它对现金流的塑造作用极大。等额本金、等额本息、先息后本、一次性还本付息，四种方式在每期还款额、利息总额、资金使用效率上差别很大。等额本息每期还款额固定，适合收入稳定的工薪客群；等额本金前期还款压力大但总利息少；先息后本前期只还利息、到期还本，适合经营性资金周转，但期末一次性还本压力大；一次性还本付息则多见于短期贷款。等额本金、等额本息等被列在还款方式的可选值里，背后对应着还款计划生成器的不同算法分支。还款方式一旦选定，就锁定了还款计划的结构，这也是后面第五节状态机和还款管理的基础。</p><p>到这里，贷前的决策链路走完了：进件、反欺诈、准入、评估、评分、定价，最后产出一份写满信贷参数的审批结论。接下来，这笔贷款要进入真正的资金交割环节：签约与放款。</p><h3 id="四-决策的传导-授信额度与定价的落地" tabindex="-1"><a class="header-anchor" href="#四-决策的传导-授信额度与定价的落地" aria-hidden="true">#</a> （四）决策的传导：授信额度与定价的落地</h3><p><img src="'+i+'" alt="图片"></p><p><strong>图2-6 授信决策落地传导链路</strong></p><p>评分和定价的产出，最终要落到两个系统对象上：授信额度和贷款合同参数。一笔申请通过后，系统要生成授信额度，把&quot;贷多少&quot;固化下来；贷款合同参数则把&quot;什么价、怎么还&quot;固化下来。授信审批通过后要经过&quot;额度开户&quot;才真正进入可用状态，这个&quot;开户&quot;动作把额度从&quot;审批结论&quot;变成&quot;可支用的额度记录&quot;。</p><p>定价决策要重点关注&quot;分群&quot;的概念。分群定价，是把客户按风险等级、客户等级、渠道来源分成不同群组，每个群组对应不同的费率区间。分群定价在系统里的实现，是&quot;客户群组 → 定价策略 → 产品费率&quot;的映射：客户属于哪个群组由评分结果决定，群组对应哪套定价策略由产品配置决定，定价策略给出具体的利率区间，再结合审批人的权限在该区间内确定最终利率。这套映射链是信贷定价系统的核心，也是循环定价流程要解决的。审批流程里的&quot;循环定价&quot;节点，就是定价策略与审批人协商定价的落点。</p><p>最后补一个容易被忽视的口径：风险定价与收益的平衡。定价不是越低越好也不是越高越好。利率高了风险溢价覆盖成本，但可能赶走好客户；利率低了客户满意度高，但可能覆盖不了坏账。所以定价决策在系统里通常要参考一个&quot;风险定价底线&quot;，低于底线的定价要审批人额外说明。我在产业金融做定价时，给每个产品都配了风险定价底线模型，底线以下不批，这条线既是风控纪律，也是定价系统的默认保护。</p><h3 id="五-把决策翻译成产品参数的完整视图" tabindex="-1"><a class="header-anchor" href="#五-把决策翻译成产品参数的完整视图" aria-hidden="true">#</a> （五）把决策翻译成产品参数的完整视图</h3><p>把风险评估到产品参数的翻译过程画成一条决策链路（下图），信贷系统的决策逻辑就更清楚了。客户进件后，数据从征信、第三方、客户自填三个来源汇入评分引擎，评分映射成风险等级，再依次驱动额度、定价、产品配置、审批权限，每一环的输出都是下一环的输入，任何一环口径变化，下游全部受影响。</p><p><img src="'+q+'" alt="图片"></p><p><strong>图2-7 决策传导链路：从风险等级到产品参数</strong></p><p>四种主流还款方式对现金流的影响差异很大，值得用一张表直接对比，这也是产品经理和工程师沟通时最常用的工具：</p><p><strong>表2-1四种主流还款方式对比</strong></p><table><thead><tr><th><strong>还款方式</strong></th><th><strong>每期还款额</strong></th><th><strong>利息总额</strong></th><th><strong>资金使用效率</strong></th><th><strong>适用客群</strong></th></tr></thead><tbody><tr><td>等额本息</td><td>固定</td><td>较高</td><td>一般</td><td>工薪、收入稳定</td></tr><tr><td>等额本金</td><td>逐期递减</td><td>较低</td><td>较好</td><td>收入前高后低</td></tr><tr><td>先息后本</td><td>前期只还息</td><td>高</td><td>最高</td><td>经营周转</td></tr><tr><td>一次性还本付息</td><td>期末一次</td><td>视期限</td><td>最高</td><td>短期周转</td></tr><tr><td>随借随还</td><td>不固定</td><td>按天计息</td><td>最高</td><td>线上循环贷、按日计息产品</td></tr></tbody></table><p>这张表解释了为什么还款方式不只是产品细节，而是风险工具：先息后本和一次性还本付息资金使用效率最高，但期末集中偿还压力也最大，只适合现金流集中在期末的客群。等额本息和等额本金把偿还压力摊到每一期，更稳但资金使用效率低。产品在设计还款方式时，本质上是在&quot;资金效率&quot;和&quot;偿还安全&quot;之间做权衡，系统实现时则要保证每种方式都能生成正确的还款计划，并在贷后准确核算。</p>',39);function m(f,x){const d=n("ExternalLinkIcon");return r(),a("div",null,[g,t("blockquote",null,[t("p",null,[o("公众号：侃西东　·　发布日期：2026-09-24　·　"),t("a",l,[o("微信原文"),s(d)])])]),b])}const y=e(_,[["render",m],["__file","012.html.vue"]]);export{y as default};
